    h += '<div class="card elev-sm gap-10"><div class="card-title">Integrasi & kunci publik</div>' + [['Midtrans', 'pembayaran & pre-auth kartu', st.pay && st.pay.j && st.pay.j.midtrans && st.pay.j.midtrans.siap], ['Xendit', 'pembayaran alternatif', st.pay && st.pay.j && st.pay.j.xendit && st.pay.j.xendit.siap], ['Google Sign-In', 'client id: ' + (cfg.googleClientId ? 'terisi' : 'kosong'), !!cfg.googleClientId], ['Facebook Login', 'app id: ' + (cfg.facebookAppId ? 'terisi' : 'kosong'), !!cfg.facebookAppId], ['Cloudflare Turnstile', 'site key: ' + (cfg.turnstileSiteKey ? 'terisi' : 'kosong'), !!cfg.turnstileSiteKey], ['SMS / WhatsApp OTP', st.auth && st.auth.j ? st.auth.j.sms : '—', st.auth && st.auth.j && st.auth.j.sms !== 'log'], ['Email transaksional', st.auth && st.auth.j ? st.auth.j.email : '—', st.auth && st.auth.j && st.auth.j.email !== 'log']].map(function (x) { return '<div class="flex items-center gap-9 t-125">' + chip(x[2] ? 'green' : 'flat', x[2] ? 'siap' : 'belum') + '<b>' + x[0] + '</b><span class="o-7 grow">' + esc(x[1]) + '</span></div>'; }).join('') + '<div class="t-115 o-6 lh-15">Mengubah kunci publik klien atau alamat server dilakukan lewat usulan tingkat tinggi (Persetujuan) — bukan langsung di localStorage.</div></div></div>';
