  AKSI.dataEkspor = function () { denganPin('Ekspor seluruh basis data (data pribadi)', function (oleh) { var d = db(); var teks = d.exportJSON(); if (window.EXO_KEUANGAN) EXO_KEUANGAN.unduh('exoclean-cadangan-' + hariIni() + '.json', teks); d.setting('cadanganTerakhir', new Date().toISOString()); EXO_PERSETUJUAN.audit(oleh, 'Mengekspor cadangan basis data', null, (teks.length / 1024).toFixed(0) + ' KB'); A.sekilas('Cadangan diekspor · ' + (teks.length / 1024).toFixed(0) + ' KB.'); }); };
  AKSI.dataImpor = function (a, v, el) { var f = el && el.files && el.files[0]; if (!f) return; var r = new FileReader(); r.onload = function () { var teks = String(r.result); try { JSON.parse(teks); } catch (e) { A.sekilas('Berkas bukan JSON yang sah.', 'err'); A.gambar(); return; } denganPin('Ajukan impor basis data dari ' + f.name + ' (menimpa data)', function (oleh) { var d = db(); d.setting('imporTertunda', teks.slice(0, 4000000)); var h = EXO_PERSETUJUAN.ajukan('data-impor', 'Impor basis data ' + f.name, (teks.length / 1024).toFixed(0) + ' KB', null, null, { nama:f.name }, oleh); lapor(h, 'Impor basis data'); }, tinggi()); }; r.readAsText(f); };
  if (window.EXO_PERSETUJUAN) EXO_PERSETUJUAN.daftarkanPenerap('data-impor', function () { var d = db(); var teks = d.setting('imporTertunda'); if (!teks) throw new Error('Berkas impor tidak ditemukan'); var admins = d.where('users', function (x) { return x.role === 'admin'; }); d.importJSON(teks); admins.forEach(function (a) { if (!d.find('users', a.id)) d.insert('users', a); }); d.setting('imporTertunda', null); return true; });
